 const items=[];
 actions.forEach(t=>{const a=S.assets.find(x=>x.id===t.asset);items.push({d:new Date(t.due+'T12:00:00'),day:true,prop:a?.name||'—',title:t.title,amt:null,rem:t.status==='Reviewed'?'Reviewed':t.due<S.asOf?'Overdue':'',over:t.status!=='Reviewed'&&t.due<S.asOf,task:t.id})});
